window.__finlexDocLoaded(10169,{"id":10169,"articles":[{"id":1000707,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"The flagship SOX Section 404(b) auditing standard governing integrated audits of Internal Control Over Financial Reporting (ICFR) and financial statements, using a top-down, risk-based approach anchored in the COSO Internal Control framework.","seq":0},{"id":1000708,"no":"AS 2201.01–.99","heading":"Top-Down Approach, Entity-Level Controls, Walkthroughs & Material Weaknesses","text":"• Top-Down Approach (AS 2201.21–.41): Start at the financial statement level → evaluate Entity-Level Controls (ELCs) and period-end financial reporting process → identify significant accounts/disclosures and relevant assertions → select key controls to test (ITGCs + automated/manual controls).\n• Testing Operating Effectiveness (AS 2201.44–.61): Test design and operating effectiveness as of year-end; perform roll-forward procedures for interim testing.\n• Deficiency Evaluation (AS 2201.62–.70): Classify into Control Deficiency, Significant Deficiency (communicated to Audit Committee), or Material Weakness (reasonable possibility of material misstatement not prevented/detected timely → triggers ADVERSE ICFR opinion!).","seq":1},{"id":1000709,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Unique US Statutory Requirement: Under SOX 404(b), SEC accelerated/large accelerated filers require an independent auditor's opinion on ICFR under AS 2201 (no equivalent mandatory ICFR audit under IFRS/ISAs, though China implemented a parallel mandatory ICFR audit for A-share listed companies under《企业内部控制审计指引》).","seq":2},{"id":1000710,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards/details/AS2201\nStatus: in_force.","seq":3}]});
